    @inputs begin
        q1::Real
        q2::Real
        q3::Real
        qd1::Real
        qd2::Real
        qd3::Real
        tm::Real
    end
    @outputs begin
        u::Real = 0.0, [unit = "V"]
        phase::Real = 0.0, [description = "0 hanging, 1 swing-up, 2 balance"]
        V::Real = 0.0, [description = "Distance to upright, the LQR cost-to-go (x - x_up)T P_lqr (x - x_up)"]
    end
    @variables caught::Int = 0, [description = "1 once the balance LQR has taken over"]
    @discrete Ts = 1e-3 begin
        e = [q1 - 1.5707963267948966, q2, q3, qd1, qd2, qd3]
        Vx = dot(e, P_lqr * e)
        caught = ifelse(tm >= t_on && (caught == 1 || Vx < V_catch), 1, 0)
        u_bal = -dot(K_lqr, e)
        s = clamp((tm - t_on) / dt_tab, 0.0, 350.0)
        uf = 0.0
        r_q1 = 0.0
        g_q1 = 0.0
        r_q2 = 0.0
        g_q2 = 0.0
        r_q3 = 0.0
        g_q3 = 0.0
        r_qd1 = 0.0
        g_qd1 = 0.0
        r_qd2 = 0.0
        g_qd2 = 0.0
        r_qd3 = 0.0
        g_qd3 = 0.0
        for k in 1:R
            w = max(0.0, 1.0 - abs(s - (k - 1)))
            uf = uf + w * u_ff[k]
            r_q1 = r_q1 + w * xr_q1[k]
            g_q1 = g_q1 + w * k_q1[k]
            r_q2 = r_q2 + w * xr_q2[k]
            g_q2 = g_q2 + w * k_q2[k]
            r_q3 = r_q3 + w * xr_q3[k]
            g_q3 = g_q3 + w * k_q3[k]
            r_qd1 = r_qd1 + w * xr_qd1[k]
            g_qd1 = g_qd1 + w * k_qd1[k]
            r_qd2 = r_qd2 + w * xr_qd2[k]
            g_qd2 = g_qd2 + w * k_qd2[k]
            r_qd3 = r_qd3 + w * xr_qd3[k]
            g_qd3 = g_qd3 + w * k_qd3[k]
        end
        u_sw = uf - (g_q1 * (q1 - r_q1) + g_q2 * (q2 - r_q2) + g_q3 * (q3 - r_q3) + g_qd1 * (qd1 - r_qd1) + g_qd2 * (qd2 - r_qd2) + g_qd3 * (qd3 - r_qd3))
        u_cmd = ifelse(tm < t_on, 0.0, ifelse(caught == 1, u_bal, u_sw))
        u = clamp(u_cmd, -u_max, u_max)
        phase = ifelse(tm < t_on, 0.0, ifelse(caught == 1, 2.0, 1.0))
        V = Vx
    end
